// Loop over input items and add a new field called 'myNewField' to the JSON of each one

const obj = {...$input.first().json, sheetsURL: "https://docs.google.com/spreadsheets/d/1ZMhBOqNKCtU9vg7oBgrpKSMwpaHfkm7W36CC4FP9FrM/edit?gid=0#gid=0" }

const row = obj;
const feedback = (row.Feedback || "").trim();
if (!feedback) {
  throw new Error("Feedback is empty; nothing to do.");
}

const approved = /(^|\b)approved(\b|$)/i.test(feedback);

const extractFileId = (url) => {
  if (!url) return null;
  const idParam = url.match(/[?&]id=([^&]+)/);
  if (idParam) return decodeURIComponent(idParam[1]);
  const pathId = url.match(/\/d\/([^/]+)/);
  if (pathId) return pathId[1];
  return null;
}

const fileId = extractFileId(row.URL);
if (!fileId) throw new Error("Could not extract fileId from URL");

const version = Number(row.Version || 0);




return {...row, feedback, approved, fileId, version };

const item = $input.first();
item.binary.data.mimeType = "image/svg+xml"
item.binary.data.fileType = "svg"

return item;

// Extract HTML from AI response
const aiResponse = $input.first().json.output;

// Extract HTML code from markdown code blocks
const htmlMatch = aiResponse.match(/```html\n([\s\S]*?)```/);
const rawHtml = htmlMatch ? htmlMatch[1] : aiResponse;

// Build complete HTML with Tailwind CDN
const completeHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UX Preview - ${$('Build Context').item.json.sessionId}</title>
    <script src="https://cdn.tailwindcss.com"></script>
</head>
<body>
    ${rawHtml}

    <!-- Version Watermark -->
    <div style="position: fixed; bottom: 10px; right: 10px; background: rgba(0,0,0,0.7); color: white; padding: 8px 12px; border-radius: 4px; font-size: 11px; font-family: monospace; z-index: 9999;">
        Session: ${$('Build Context').item.json.sessionId.slice(0, 12)}... | ${new Date().toLocaleTimeString()}
    </div>
</body>
</html>
`;

return {
  json: {
    html: completeHtml,
    rawHtml: rawHtml,
    sessionId: $('Build Context').item.json.sessionId,
    timestamp: new Date().toISOString(),
    inputType: $('Build Context').item.json.inputType
  }
};

// Format conversation history for AI
const history = $input.all();
const contextData = $('Build Context').item.json;

const messages = [];
let latestVersion = 0;
let originalRequirements = '';

// Process all messages
for (const item of history) {
  const fields = item.json.fields;

  // Track latest version
  if (fields.design_version > latestVersion) {
    latestVersion = fields.design_version;
  }

  // Capture original requirements
  if (fields.type === 'pm' && fields.requirements) {
    originalRequirements = fields.requirements;
  }

  // Build message for AI context
  let content = fields.content;

  // For AI responses, include snippet of HTML generated
  if (fields.type === 'ai' && fields.html_output) {
    content += `\n\n[Generated HTML v${fields.design_version}]: ${fields.html_output.substring(0, 300)}...`;
  }

  messages.push({
    role: fields.role,
    content: content,
    type: fields.type,
    version: fields.design_version
  });
}

// Build context summary
const contextSummary = `
=== CONVERSATION CONTEXT ===
Chat ID: ${contextData.chatId}
Original Requirements: ${originalRequirements || 'N/A'}
Current Version: ${latestVersion}
Total Messages: ${messages.length}

=== CONVERSATION HISTORY ===
${messages.map((m, i) => `[${i + 1}] ${m.type.toUpperCase()} (v${m.version}): ${m.content}`).join('\n\n')}

=== NEW REQUEST ===
${contextData.inputType === 'chat' ? 'User: ' + contextData.userMessage : 'PM Requirements: ' + contextData.requirements}
`;

return {
  json: {
    messages: messages,
    contextSummary: contextSummary,
    latestVersion: latestVersion,
    newVersion: latestVersion + 1,
    originalRequirements: originalRequirements,
    chatId: contextData.chatId,
    inputType: contextData.inputType,
    userMessage: contextData.userMessage,
    requirements: contextData.requirements
  }
};

// Extract HTML from AI response
const aiResponse = $input.first().json.output;
const contextData = $('Format History for AI').item.json;

// Extract HTML code from markdown
const htmlMatch = aiResponse.match(/```html\n([\s\S]*?)```/);
const rawHtml = htmlMatch ? htmlMatch[1] : aiResponse;

// Build complete HTML
const completeHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UX Preview v${contextData.newVersion} - ${contextData.chatId}</title>
    <script src="https://cdn.tailwindcss.com"></script>
</head>
<body>
    ${rawHtml}

    <!-- Version Watermark -->
    <div style="position: fixed; bottom: 10px; right: 10px; background: rgba(0,0,0,0.7); color: white; padding: 8px 12px; border-radius: 4px; font-size: 11px; font-family: monospace; z-index: 9999;">
        v${contextData.newVersion} | Chat: ${contextData.chatId.slice(0, 8)}... | ${new Date().toLocaleTimeString()}
    </div>
</body>
</html>
`;

return {
  json: {
    html: completeHtml,
    rawHtml: rawHtml,
    chatId: contextData.chatId,
    version: contextData.newVersion,
    timestamp: new Date().toISOString(),
    aiResponse: aiResponse.replace(htmlMatch ? htmlMatch[0] : '', '').trim() // AI's explanation without HTML
  }
};

return [{
  json: {
    N8N_SPOONTACULAR_BASE_URL: $env.N8N_SPOONTACULAR_BASE_URL,
    N8N_SPOONTACULAR_API_KEY: $env.N8N_SPOONTACULAR_API_KEY,
    N8N_MOVIE_GLUE_BASE_URL: $env.N8N_MOVIE_GLUE_BASE_URL,
    N8N_MOVIE_GLUE_API_KEY: $env.N8N_MOVIE_GLUE_API_KEY,
    N8N_WEATHER_BASE_URL: $env.N8N_WEATHER_BASE_URL,
    N8N_WEATHER_BASE_API_KEY: $env.N8N_WEATHER_BASE_API_KEY,
    N8N_MONDAY_API_KEY: $env.N8N_MONDAY_API_KEY,
    N8N_GOOGLE_SHEET_API_KEY: $env.N8N_GOOGLE_SHEET_API_KEY,
    N8N_GOOGLE_API_KEY: $env.N8N_GOOGLE_API_KEY,
    N8N_PINECONE_API_KEY: $env.N8N_PINECONE_API_KEY,
    N8N_MEAL_AGG_API_KEY: $env.N8N_MEAL_AGG_API_KEY,
    N8N_SUPP_AGG_API_KEY: $env.N8N_SUPP_AGG_API_KEY
  }
}];
